html,
body {
  min-height: 100%;
  margin: 0;
}

body {
  font-family: Arial, "Microsoft YaHei", sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

.app-shell {
  min-height: 100vh;
  padding: 56px clamp(20px, 5vw, 72px);
}

.hero {
  max-width: 860px;
  padding: 72px 0 56px;
}

.eyebrow {
  margin: 0 0 12px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  max-width: 780px;
  margin-bottom: 18px;
  font-size: clamp(42px, 8vw, 88px);
  line-height: 0.96;
  letter-spacing: 0;
}

h2 {
  margin-bottom: 12px;
  font-size: 28px;
  letter-spacing: 0;
}

.lede {
  max-width: 680px;
  color: var(--muted);
  font-size: 20px;
  line-height: 1.65;
}

.panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 360px);
  gap: 32px;
  align-items: start;
  max-width: 980px;
  border-top: 1px solid var(--line);
  padding-top: 28px;
}

.panel p {
  color: var(--muted);
  line-height: 1.7;
}

.quick-links {
  display: grid;
  gap: 10px;
}

.quick-links a {
  display: block;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 13px 15px;
  background: rgba(255, 255, 255, 0.48);
  color: var(--accent-strong);
  font-weight: 700;
}

.quick-links a:hover {
  border-color: var(--accent);
}

@media (max-width: 720px) {
  .app-shell {
    padding: 32px 18px;
  }

  .hero {
    padding: 48px 0 36px;
  }

  .panel {
    grid-template-columns: 1fr;
  }
}

