"use client";

import { useMemo, useState } from "react";
import {
  CheckCircle2,
  Headphones,
  Loader2,
  Play,
  RotateCcw,
  Send,
  Square,
} from "lucide-react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";

type PracticeType = "listening" | "grammar";
type Difficulty = "easy" | "medium" | "hard";
type Answer = "A" | "B" | "C" | "D";

type GeneratedQuestion = {
  id: string;
  type: PracticeType;
  subtype: string;
  difficulty: Difficulty;
  prompt: string;
  options: Record<Answer, string>;
  answer: Answer;
  explanationZh: string;
  tags: string[];
  listeningScript?: string | null;
  grammarPoint?: string | null;
};

type ApiResponse<T> =
  | { ok: true; data: T }
  | { ok: false; error: { code: string; message: string } };

type PracticeWorkspaceProps = {
  practiceType: PracticeType;
};

const answers: Answer[] = ["A", "B", "C", "D"];

const listeningSubtypes = [
  { value: "picture-description", label: "图片描述风格" },
  { value: "question-response", label: "问答题风格" },
  { value: "short-conversation", label: "简短对话" },
  { value: "short-talk", label: "简短讲话" },
];

const grammarSubtypes = [
  { value: "sentence-completion", label: "单句填空" },
  { value: "part-of-speech", label: "词性选择" },
  { value: "tense-voice", label: "时态 / 语态" },
  { value: "preposition-conjunction", label: "介词 / 连词" },
  { value: "business-context", label: "商务语境" },
];

const difficultyLabels = {
  easy: "简单",
  medium: "中等",
  hard: "困难",
};

export function PracticeWorkspace({ practiceType }: PracticeWorkspaceProps) {
  const isListening = practiceType === "listening";
  const subtypes = isListening ? listeningSubtypes : grammarSubtypes;
  const [subtype, setSubtype] = useState(subtypes[0].value);
  const [difficulty, setDifficulty] = useState<Difficulty>("medium");
  const [count, setCount] = useState(isListening ? 3 : 5);
  const [tags, setTags] = useState("");
  const [grammarPoint, setGrammarPoint] = useState("时态");
  const [questions, setQuestions] = useState<GeneratedQuestion[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<Answer | null>(null);
  const [result, setResult] = useState<{
    isCorrect: boolean;
    correctAnswer: Answer;
    explanationZh: string;
  } | null>(null);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const currentQuestion = questions[currentIndex];
  const submitted = Boolean(result);

  const parsedTags = useMemo(
    () =>
      tags
        .split(",")
        .map((tag) => tag.trim())
        .filter(Boolean),
    [tags],
  );

  async function generateQuestions() {
    setLoading(true);
    setError(null);
    setQuestions([]);
    setResult(null);
    setSelectedAnswer(null);

    try {
      const response = await fetch("/api/ai/generate-questions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          practiceType,
          subtype,
          difficulty,
          count,
          tags: parsedTags,
          grammarPoint: isListening ? undefined : grammarPoint,
        }),
      });
      const payload = (await response.json()) as ApiResponse<{
        questions: GeneratedQuestion[];
      }>;

      if (!payload.ok) {
        throw new Error(payload.error.message);
      }

      setQuestions(payload.data.questions);
      setCurrentIndex(0);
    } catch (generateError) {
      setError(
        generateError instanceof Error
          ? generateError.message
          : "生成题目失败。",
      );
    } finally {
      setLoading(false);
    }
  }

  async function submitAnswer() {
    if (!currentQuestion || !selectedAnswer) {
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const response = await fetch("/api/practice-records", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          questionId: currentQuestion.id,
          userAnswer: selectedAnswer,
          timeSpentSeconds: 0,
        }),
      });
      const payload = (await response.json()) as ApiResponse<{
        result: {
          isCorrect: boolean;
          correctAnswer: Answer;
          explanationZh: string;
        };
      }>;

      if (!payload.ok) {
        throw new Error(payload.error.message);
      }

      setResult(payload.data.result);
    } catch (submitError) {
      setError(
        submitError instanceof Error ? submitError.message : "提交答案失败。",
      );
    } finally {
      setSubmitting(false);
    }
  }

  function nextQuestion() {
    window.speechSynthesis?.cancel();
    setSpeaking(false);
    setResult(null);
    setSelectedAnswer(null);
    setCurrentIndex((index) => Math.min(index + 1, questions.length - 1));
  }

  function replay() {
    if (!currentQuestion || !("speechSynthesis" in window)) {
      setError("当前浏览器不支持语音朗读。");
      return;
    }

    window.speechSynthesis.cancel();
    const spoken = [
      currentQuestion.listeningScript,
      ...answers.map((answer) => `Option ${answer}. ${currentQuestion.options[answer]}`),
    ]
      .filter(Boolean)
      .join(" ");
    const utterance = new SpeechSynthesisUtterance(spoken);
    utterance.rate = 1;
    utterance.onend = () => setSpeaking(false);
    setSpeaking(true);
    window.speechSynthesis.speak(utterance);
  }

  function stopSpeech() {
    window.speechSynthesis?.cancel();
    setSpeaking(false);
  }

  return (
    <div className="space-y-6">
      <section className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div className="space-y-3">
          <Badge variant="outline" className="gap-1.5">
            {isListening ? (
              <Headphones className="size-3.5" />
            ) : (
              <CheckCircle2 className="size-3.5" />
            )}
            {isListening ? "听力练习" : "语法练习"}
          </Badge>
          <div>
            <h1 className="text-3xl font-semibold tracking-normal md:text-5xl">
              {isListening ? "听力练习" : "语法练习"}
            </h1>
            <p className="mt-3 max-w-2xl text-base leading-7 text-muted-foreground">
              {isListening
                ? "答题前只显示 A/B/C/D，英文选项由浏览器朗读。"
                : "选择语法点并生成托业阅读风格练习题。"}
            </p>
          </div>
        </div>
      </section>

      {error ? (
        <Alert variant="destructive">
          <AlertTitle>操作失败</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      <Card>
        <CardHeader>
          <CardTitle>生成设置</CardTitle>
          <CardDescription>
            前端只请求本地 API，API Key 只在服务端读取。
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-5">
          <label className="space-y-2 md:col-span-2">
            <span className="text-sm font-medium">题型</span>
            <Select value={subtype} onValueChange={setSubtype}>
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {subtypes.map((item) => (
                  <SelectItem key={item.value} value={item.value}>
                    {item.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </label>
          <label className="space-y-2">
            <span className="text-sm font-medium">难度</span>
            <Select
              value={difficulty}
              onValueChange={(value) => setDifficulty(value as Difficulty)}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(difficultyLabels).map(([value, label]) => (
                  <SelectItem key={value} value={value}>
                    {label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </label>
          <label className="space-y-2">
            <span className="text-sm font-medium">题量</span>
            <Input
              type="number"
              min={1}
              max={10}
              value={count}
              onChange={(event) => setCount(Number(event.target.value))}
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-medium">标签</span>
            <Input
              value={tags}
              onChange={(event) => setTags(event.target.value)}
              placeholder="business, meeting"
            />
          </label>
          {!isListening ? (
            <label className="space-y-2 md:col-span-2">
              <span className="text-sm font-medium">语法点</span>
              <Input
                value={grammarPoint}
                onChange={(event) => setGrammarPoint(event.target.value)}
              />
            </label>
          ) : null}
          <div className="flex items-end md:col-span-3">
            <Button onClick={generateQuestions} disabled={loading}>
              {loading ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <RotateCcw className="size-4" />
              )}
              {loading ? "生成中" : "生成题目"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {currentQuestion ? (
        <Card>
          <CardHeader>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <CardTitle>
                  第 {currentIndex + 1} / {questions.length} 题
                </CardTitle>
                <CardDescription>{currentQuestion.prompt}</CardDescription>
              </div>
              {isListening ? (
                <div className="flex gap-2">
                  <Button variant="outline" onClick={replay}>
                    <Play className="size-4" />
                    {speaking ? "重播" : "播放"}
                  </Button>
                  <Button variant="ghost" onClick={stopSpeech}>
                    <Square className="size-4" />
                    停止
                  </Button>
                </div>
              ) : null}
            </div>
          </CardHeader>
          <CardContent className="space-y-5">
            <div className="grid gap-3 sm:grid-cols-2">
              {answers.map((answer) => (
                <Button
                  key={answer}
                  variant={selectedAnswer === answer ? "secondary" : "outline"}
                  className={cn("h-auto justify-start gap-3 py-4 text-left")}
                  onClick={() => setSelectedAnswer(answer)}
                  disabled={submitted}
                >
                  <span className="flex size-7 shrink-0 items-center justify-center rounded-md border bg-background font-semibold">
                    {answer}
                  </span>
                  <span className="whitespace-normal">
                    {isListening && !submitted
                      ? "选项正文将在提交后显示"
                      : currentQuestion.options[answer]}
                  </span>
                </Button>
              ))}
            </div>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-sm text-muted-foreground">
                {selectedAnswer ? `已选择 ${selectedAnswer}` : "请选择答案"}
              </p>
              <Button
                onClick={submitAnswer}
                disabled={!selectedAnswer || submitted || submitting}
              >
                {submitting ? (
                  <Loader2 className="size-4 animate-spin" />
                ) : (
                  <Send className="size-4" />
                )}
                提交答案
              </Button>
            </div>
            {result ? (
              <>
                <Separator />
                <Alert>
                  <AlertTitle>
                    {result.isCorrect ? "回答正确" : "回答错误"}
                  </AlertTitle>
                  <AlertDescription>
                    正确答案：{result.correctAnswer}。{result.explanationZh}
                  </AlertDescription>
                </Alert>
                {currentIndex < questions.length - 1 ? (
                  <Button variant="outline" onClick={nextQuestion}>
                    下一题
                  </Button>
                ) : null}
              </>
            ) : null}
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>等待生成</CardTitle>
            <CardDescription>
              {isListening
                ? "生成后会先隐藏英文选项正文，只展示 A/B/C/D。"
                : "生成后可直接答题并查看中文解析。"}
            </CardDescription>
