import { NextResponse } from "next/server";

import { AppError, isAppError } from "@/lib/errors";
import {
  generateQuestionsWithMaas,
  type QuestionGenerationRequest,
} from "@/lib/question-generation";
import { prisma } from "@/lib/prisma";
import type { PracticeType } from "@/lib/question-validation";

const practiceTypes = ["listening", "grammar"];
const difficulties = ["easy", "medium", "hard"];

function isPracticeType(value: unknown): value is PracticeType {
  return typeof value === "string" && practiceTypes.includes(value);
}

function isDifficulty(
  value: unknown,
): value is QuestionGenerationRequest["difficulty"] {
  return typeof value === "string" && difficulties.includes(value);
}

function normalizeTags(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((tag): tag is string => typeof tag === "string")
    .map((tag) => tag.trim())
    .filter(Boolean)
    .slice(0, 8);
}

function validateRequestBody(body: unknown): QuestionGenerationRequest {
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new AppError("REQUEST_INVALID", "璇锋眰浣撳繀椤绘槸 JSON 瀵硅薄銆?, 400);
  }

  const value = body as Record<string, unknown>;
  const practiceType = value.practiceType;
  const subtype = typeof value.subtype === "string" ? value.subtype.trim() : "";
  const difficulty = value.difficulty;
  const count = Number(value.count);
  const grammarPoint =
    typeof value.grammarPoint === "string" ? value.grammarPoint.trim() : "";

  if (!isPracticeType(practiceType)) {
    throw new AppError(
      "REQUEST_INVALID",
      "缁冧範绫诲瀷蹇呴』鏄?listening 鎴?grammar銆?,
      400,
    );
  }

  if (!subtype || subtype.length > 80) {
    throw new AppError("REQUEST_INVALID", "棰樺瀷涓嶈兘涓虹┖涓斾笉鑳借繃闀裤€?, 400);
  }

  if (!isDifficulty(difficulty)) {
    throw new AppError(
      "REQUEST_INVALID",
      "闅惧害蹇呴』鏄?easy銆乵edium 鎴?hard銆?,
      400,
    );
  }

  if (!Number.isInteger(count) || count < 1 || count > 10) {
    throw new AppError("REQUEST_INVALID", "棰橀噺蹇呴』鏄?1 鍒?10 鐨勬暣鏁般€?, 400);
  }

  return {
    practiceType,
    subtype,
    difficulty,
    count,
    tags: normalizeTags(value.tags),
    grammarPoint,
  };
}

function jsonError(error: AppError) {
  return NextResponse.json(
    {
      ok: false,
      error: {
        code: error.code,
        message: error.message,
      },
    },
    { status: error.status },
  );
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const input = validateRequestBody(body);
    const questions = await generateQuestionsWithMaas(input);

    const savedQuestions = await prisma.$transaction(
      questions.map((question) =>
        prisma.question.create({
          data: {
            type: question.type,
            subtype: question.subtype,
            difficulty: question.difficulty,
            prompt: question.prompt,
            optionsJson: JSON.stringify(question.options),
            answer: question.answer,
            explanationZh: question.explanationZh,
            tagsJson: JSON.stringify(question.tags),
            listeningScript: question.listeningScript,
            grammarPoint: question.grammarPoint,
            source: "maas",
          },
        }),
      ),
    );

    return NextResponse.json({
      ok: true,
      data: {
        questions: savedQuestions.map((question) => ({
          ...question,
          options: JSON.parse(question.optionsJson) as Record<string, string>,
          tags: JSON.parse(question.tagsJson) as string[],
          optionsJson: undefined,
          tagsJson: undefined,
        })),
        source: "maas",
      },
    });
  } catch (error) {
    if (isAppError(error)) {
      return jsonError(error);
    }

    return jsonError(
      new AppError(
        "AI_GENERATION_FAILED",
        "鐢熸垚棰樼洰澶辫触锛岃绋嶅悗閲嶈瘯銆?,
        500,
      ),
    );
  }
}

import { generateTextWithMaas } from "@/lib/maas-client";
import {
  parseAndValidateQuestions,
  type PracticeType,
  type ValidatedQuestion,
} from "@/lib/question-validation";
import { buildGrammarPrompt } from "@/prompts/generate-grammar-question";
import { buildListeningPrompt } from "@/prompts/generate-listening-question";

export type QuestionGenerationRequest = {
  practiceType: PracticeType;
  subtype: string;
  difficulty: "easy" | "medium" | "hard";
  count: number;
  tags: string[];
  grammarPoint?: string;
};

export function buildQuestionPrompt(request: QuestionGenerationRequest) {
  return request.practiceType === "listening"
    ? buildListeningPrompt(request)
    : buildGrammarPrompt(request);
}

export async function generateQuestionsWithMaas(
  request: QuestionGenerationRequest,
): Promise<ValidatedQuestion[]> {
  const prompt = buildQuestionPrompt(request);
  const raw = await generateTextWithMaas([
    {
      role: "system",
      content:
        "You generate structured TOEIC practice questions and return strict JSON only.",
    },
    {
      role: "user",
      content: prompt,
    },
  ]);

  return parseAndValidateQuestions(raw, request.practiceType);
}

export const DEFAULT_MAAS_BASE_URL = "https://api.modelarts-maas.com/v1/";
export const DEFAULT_MAAS_MODEL = "deepseek-v3.2";

export const DIFFICULTIES = ["easy", "medium", "hard"] as const;

export type Difficulty = (typeof DIFFICULTIES)[number];

export const DEFAULT_USER_SETTING = {
  defaultDifficulty: "medium",
  defaultQuestionCount: 5,
  speechRate: 1,
} as const;

