import Link from "next/link";
import {
  ArrowRight,
  BarChart3,
  BookOpenCheck,
  ClipboardList,
  Headphones,
  Target,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { getStats } from "@/lib/stats-service";

const quickLinks = [
  {
    href: "/listening",
    label: "听力练习",
    description: "隐藏选项正文，先听再答",
    icon: Headphones,
  },
  {
    href: "/grammar",
    label: "语法练习",
    description: "围绕语法点生成托业题",
    icon: BookOpenCheck,
  },
  {
    href: "/mistakes",
    label: "错题本",
    description: "回看错因，标记掌握",
    icon: ClipboardList,
  },
  {
    href: "/stats",
    label: "学习统计",
    description: "查看正确率和薄弱标签",
    icon: BarChart3,
  },
];

export default async function Home() {
  const stats = await getStats();
  const statItems = [
    { label: "今日练习", value: stats.todayCount, hint: "题" },
    { label: "今日正确率", value: `${stats.todayAccuracy}%`, hint: "本日" },
    { label: "总练习", value: stats.totalCount, hint: "题" },
    { label: "当前错题", value: stats.activeMistakeCount, hint: "待复习" },
  ];

  return (
    <div className="space-y-8">
      <section className="grid gap-6 rounded-lg border bg-card p-5 shadow-sm md:grid-cols-[1.3fr_0.7fr] md:p-7">
        <div className="space-y-5">
          <Badge variant="outline" className="w-fit gap-1.5 border-emerald-200 bg-emerald-50 text-emerald-800">
            <Target className="size-3.5" />
            本机个人学习台
          </Badge>
          <div className="space-y-3">
            <h1 className="text-3xl font-semibold tracking-normal md:text-5xl">
              TOEIC Practice Studio
            </h1>
            <p className="max-w-2xl text-base leading-7 text-muted-foreground">
              用 MaaS 生成听力与语法题，记录每次练习，并把错题沉淀成本机复习清单。
            </p>
          </div>
          <div className="flex flex-col gap-3 sm:flex-row">
            <Button asChild>
              <Link href="/listening">
                <Headphones className="size-4" />
                开始听力
              </Link>
            </Button>
            <Button variant="outline" asChild>
              <Link href="/grammar">
                <BookOpenCheck className="size-4" />
                开始语法
              </Link>
            </Button>
          </div>
        </div>

        <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-1">
          <div className="rounded-lg border bg-emerald-50/70 p-4">
            <p className="text-sm text-emerald-900/70">今日状态</p>
            <p className="mt-2 text-3xl font-semibold text-emerald-950">
              {stats.todayCount > 0 ? `${stats.todayCount} 题` : "待开始"}
            </p>
          </div>
          <div className="rounded-lg border bg-amber-50/70 p-4">
            <p className="text-sm text-amber-900/70">当前错题</p>
            <p className="mt-2 text-3xl font-semibold text-amber-950">
              {stats.activeMistakeCount}
            </p>
          </div>
        </div>
      </section>

      <section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {statItems.map((item) => (
          <Card key={item.label} size="sm" className="transition-colors hover:border-emerald-200">
            <CardHeader>
              <CardDescription>{item.label}</CardDescription>
              <CardTitle className="flex items-end gap-2 text-3xl">
                {item.value}
                <span className="pb-1 text-sm font-normal text-muted-foreground">
                  {item.hint}
                </span>
              </CardTitle>
            </CardHeader>
          </Card>
        ))}
      </section>

      <section className="grid gap-4 lg:grid-cols-4">
        {quickLinks.map((item) => {
          const Icon = item.icon;

          return (
            <Link
              key={item.href}
              href={item.href}
              className="group rounded-lg border bg-card p-4 shadow-sm transition-colors hover:border-emerald-200 hover:bg-emerald-50/40"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="space-y-2">
                  <div className="flex items-center gap-2 font-medium">
                    <Icon className="size-4 text-emerald-700" />
                    {item.label}
                  </div>
                  <p className="text-sm leading-6 text-muted-foreground">
                    {item.description}
                  </p>
                </div>
                <ArrowRight className="mt-0.5 size-4 text-muted-foreground transition-transform group-hover:translate-x-0.5" />
              </div>
            </Link>
          );
        })}
      </section>
    </div>
  );
}

