"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  BarChart3,
  BookOpenCheck,
  ClipboardList,
  Headphones,
  Home,
  Settings,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const navItems = [
  { href: "/", label: "首页", icon: Home },
  { href: "/listening", label: "听力练习", icon: Headphones },
  { href: "/grammar", label: "语法练习", icon: BookOpenCheck },
  { href: "/mistakes", label: "错题本", icon: ClipboardList },
  { href: "/stats", label: "学习统计", icon: BarChart3 },
  { href: "/settings", label: "设置", icon: Settings },
];

export function AppShell({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  return (
    <div className="min-h-screen bg-muted/30 text-foreground">
      <header className="sticky top-0 z-40 border-b bg-background/90 backdrop-blur">
        <div className="mx-auto flex max-w-6xl flex-col gap-4 px-4 py-4 md:flex-row md:items-center md:justify-between md:px-6">
          <Link href="/" className="min-w-0">
            <p className="truncate text-base font-semibold tracking-normal">
              TOEIC Practice Studio
            </p>
            <p className="text-xs text-muted-foreground">本机个人版托业练习</p>
          </Link>
          <nav className="flex gap-2 overflow-x-auto pb-1" aria-label="主导航">
            {navItems.map((item) => {
              const Icon = item.icon;
              const active = pathname === item.href;

              return (
                <Button
                  key={item.href}
                  variant={active ? "secondary" : "ghost"}
                  size="sm"
                  asChild
                  className={cn(
                    "shrink-0 transition-colors",
                    active &&
                      "border border-emerald-200 bg-emerald-50 text-emerald-950 hover:bg-emerald-50",
                  )}
                >
                  <Link
                    href={item.href}
                    aria-current={active ? "page" : undefined}
                  >
                    <Icon className="size-4" />
                    {item.label}
                  </Link>
                </Button>
              );
            })}
          </nav>
        </div>
      </header>
      <main className="mx-auto w-full max-w-6xl px-4 py-8 md:px-6 md:py-10">
        {children}
      </main>
    </div>
  );
}

import { PracticeWorkspace } from "@/components/practice-workspace";

export default function ListeningPage() {
  return <PracticeWorkspace practiceType="listening" />;
}
import { PracticeWorkspace } from "@/components/practice-workspace";

export default function GrammarPage() {
  return <PracticeWorkspace practiceType="grammar" />;
}

