const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
  await page.route('**/api/ai/generate-questions', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        ok: true,
        data: {
          questions: [{
            id: 'ui-smoke-question-1',
            type: 'listening',
            subtype: 'short-conversation',
            difficulty: 'medium',
            prompt: 'What does the speaker suggest?',
            options: {
              A: 'Review the sales report tomorrow.',
              B: 'Call the client this afternoon.',
              C: 'Reserve a conference room.',
              D: 'Send the invoice next week.'
            },
            answer: 'B',
            explanationZh: '说话人建议今天下午联系客户。',
            tags: ['ui-smoke'],
            listeningScript: 'Please call the client this afternoon to confirm the meeting time.'
          }]
        }
      })
    });
  });
  await page.route('**/api/practice-records', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        ok: true,
        data: {
          record: { id: 'ui-smoke-record-1' },
          result: {
            isCorrect: false,
            correctAnswer: 'B',
            explanationZh: '说话人建议今天下午联系客户。'
          }
        }
      })
    });
  });

  await page.goto('http://127.0.0.1:3000/listening', { waitUntil: 'networkidle' });
  await page.getByRole('button', { name: /生成题目/ }).click();
  await page.getByText('What does the speaker suggest?').waitFor();
  const hiddenBeforeSubmit = !(await page.getByText('Review the sales report tomorrow.').isVisible().catch(() => false));
  await page.getByRole('button', { name: /A 提交后显示英文选项正文/ }).click();
  await page.getByRole('button', { name: /提交答案/ }).click();
  await page.getByText('本组完成').waitFor();
  const optionVisibleAfterSubmit = await page.getByText('Review the sales report tomorrow.').isVisible();
  const completionVisible = await page.getByRole('link', { name: /查看错题/ }).isVisible();
  await page.screenshot({ path: path.join('output', 'playwright', 'v1-3-completion.png'), fullPage: true });
  await browser.close();
  console.log(JSON.stringify({ hiddenBeforeSubmit, optionVisibleAfterSubmit, completionVisible }, null, 2));
  if (!hiddenBeforeSubmit || !optionVisibleAfterSubmit || !completionVisible) process.exit(1);
})();
