{"command":"@'
const { chromium } = require('playwright');
const path = require('path');

const viewports = [
  ['desktop', { width: 1440, height: 1100 }],
  ['mobile', { width: 390, height: 1200 }],
];
const pages = [
  ['home', 'http://127.0.0.1:3000/'],
  ['stats', 'http://127.0.0.1:3000/stats'],
  ['listening', 'http://127.0.0.1:3000/listening'],
  ['grammar', 'http://127.0.0.1:3000/grammar'],
];

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  for (const [viewportName, viewport] of viewports) {
    const page = await browser.newPage({ viewport });
    for (const [name, url] of pages) {
      await page.goto(url, { waitUntil: 'networkidle' });
      await page.screenshot({ path: path.join('output', 'playwright', `v1-4-${name}-${viewportName}.png`), fullPage: true });
      const overflowCount = await page.locator('body *').evaluateAll((nodes) => {
        const vw = document.documentElement.clientWidth;
        return nodes.filter((node) => {
          const element = node;
          const text = (element.textContent || '').trim();
          if (!text || text.length > 80) return false;
          const rect = element.getBoundingClientRect();
          if (rect.width === 0 || rect.height === 0) return false;
          return rect.left < -1 || rect.right > vw + 1;
        }).length;
      });
      console.log(`${name}-${viewportName}=OK overflowCandidates=${overflowCount}`);
    }
    await page.close();
  }
  await browser.close();
})();
